SELECT i.facility_key, i.facility_name, COUNT(*) AS eligible_discharges, SUM(CASE WHEN EXISTS (SELECT 1 FROM encounter_mart r WHERE r.patient_id = i.patient_id AND datetime(r.admit_at) > datetime(i.discharge_at) AND datetime(r.admit_at) <= datetime(i.discharge_at, '+' || :window_days || ' days') AND r.admit_kind = :return_kind AND r.admit_source <> :exclude_source) THEN 1 ELSE 0 END) AS readmitted_discharges FROM encounter_mart i WHERE i.disposition = :index_disposition AND datetime(i.discharge_at, '+' || :window_days || ' days') <= datetime(:as_of) GROUP BY i.facility_key, i.facility_name
